-- PT122-S4-Q13. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT122-S4-Q13$batch05$ AND q.stimulus=$batch05$It is due to a misunderstanding that most modern sculpture is monochromatic. When ancient sculptures were exhumed years ago, they were discovered to be uncolored. No one at the time had reason to believe, as we now do, that the sculptures had originally been colorfully painted, but that centuries of exposure to moisture washed away the paint.$batch05$ AND q.prompt=$batch05$Which one of the following is an assumption on which the argument depends?$batch05$ AND q.correct_choice=$batch05$B$batch05$) THEN RAISE EXCEPTION 'Question changed: PT122-S4-Q13'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT122-S4-Q13$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S4-Q13'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT122-S4-Q13$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$Most modern sculpture is monochromatic because of a misunderstanding.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Ancient sculptures were dug up uncolored. At the time, no one knew the paint had washed off over the centuries.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$The evidence is a mistake about *ancient* sculpture. The conclusion blames that mistake for how *modern* sculpture looks. That only works if modern sculptors were taking their cue from the ancient ones. Without that, the old mistake is just a fun fact.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A link: modern sculpture was shaped by beliefs about ancient sculpture.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT122-S4-Q13$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$The natural beauty of the materials is a different explanation for plain sculpture, and the argument does not need it.$batch05$), ($batch05$B$batch05$, $batch05$Negate it: "modern sculpture has *not* been influenced by beliefs about ancient sculpture." Then the misunderstanding about the ancients cannot explain why modern work is monochromatic.$batch05$), ($batch05$C$batch05$, $batch05$This is the top trap, because the stimulus talks about moisture washing paint away. But how modern sculpture holds up to moisture has nothing to do with why it is made without color.$batch05$), ($batch05$D$batch05$, $batch05$Paintings that show sculptures might be a clue someone missed, but the argument does not need that clue to exist.$batch05$), ($batch05$E$batch05$, $batch05$This predicts the future. The argument explains the past, and works whether or not sculptors change course.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT122-S4-Q13$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
